%[text] Test your function by using it to solve a problem.
% Define the parameters and boundary functions for the problem
L = 4;                   % Length of the rod
gamma = 3;               % Diffusivity, gamma > 0
dx = 0.1;                % Spatial step size
tEnd = 0.15;             % The time at which to finish the approximation
f = @(x) x.^2-4.*x;      % u(0,x)
alpha = @(t) sin(100*t); % u(t,0)
% Using the piecewise function requires a symbolic function
syms betaFunc(t)
betaFunc(t) = piecewise((0 <= t) & (t < 0.5), ...
    t,(0.5 <= t) & (t <= 1),1-t,0);       % u(t,L)
% To ensure that the output of beta is a double
beta = @(t) double(betaFunc(t));

u = explicitPDE(f,alpha,beta,tEnd,dx,gamma,L);
%[text] Plot the initial value `u0` and the final value `u` on the same plot.
plot(0:dx:L,f(0:dx:L))
hold on
plot(0:dx:L,[alpha(tEnd);u;beta(tEnd)])
hold off
title("Solving $\frac{\partial u}{\partial t} = \gamma \frac{\partial^2 u}{\partial x^2}$","Interpreter","latex")
subtitle("$t=$"+tEnd,"Interpreter","latex")
xlabel("$x$","Interpreter","latex")
ylabel("$u$","Interpreter","latex")
legend(["u(0,x)" "u(t,x)"],"Location","north")
%%
%[text] **Reference Output**
%[text] With $L=4${"altText":"L=4"}, $\\Delta x=0.1${"altText":"Delta x=0.1"}, and $\\frac{\\partial u}{\\partial t} = 3\\frac{\\partial^2u}{\\partial x^2}${"altText":"(partial u)\/(partial t) = 3(partial^2 u)\/(partial x^2)"} with $u(0,x) = x^2-4x${"altText":"u(0,x) = x^2-4x"}, $u(t,0)=\\sin(100t)${"altText":"u(t,0)=sin(100t)"} and $u(t,4) = \\begin{cases} t & 0 \\leq t \< 0.5 \\\\ 1-t & 0.5 \\leq t \< 1 \\\\ 0 & \\text{else} \\end{cases}${"altText":"u(t,4) = cases: t for 0 \<= t \< 0.5 ; 1-t for 0.5 \<= t \< 1 ; 0 for else"}, you should have the following results at $t=0.05${"altText":"t=0.05"}, $t= 0.1${"altText":"t= 0.1"}, $t=0.15${"altText":"t=0.15"} and $t=0.2${"altText":"t=0.2"}.
%[text]{"align":"center"} ![Screenshot of expected results at t=0.05](text:image:832a) ![Screenshot of expected results at t=0.1](text:image:29cf)
%[text]{"align":"center"} ![Screenshot of expected results at t=0.15](text:image:4584) ![Screenshot of expected results at t=0.2](text:image:7777)
