%[text] end
%[text] ```
%[text] Test the combined output by uncommenting the code below and running `implicitPDE` for `t < 0.01`, and `cnPDEu0` for `0.01 < t < 5`. 
% tEnd1 = 0.01;
% dx = 0.01;
% tFinal = 5;
% u1 = implicitPDE(f,alpha,beta,tEnd1,dx,gamma,L);
% hold on
% u = cnPDEu0([alpha(tEnd1);u1;beta(tEnd1)],alpha,beta,tFinal,dx,gamma,L,tEnd1);
% hold off
%%
%[text] %[text:anchor:H_280BB21C] ## Built-in solver: `pdepe`
%[text] MATLAB solves 1-D parabolic and elliptic partial differential equations of the form
%[text]{"align":"center"} $c\\left(x,t,u,\\frac{\\partial u}{\\partial x}\\right)\\frac{\\partial u}{\\partial t} = x^{-m}\\frac{\\partial}{\\partial x}\\left(x^mf\\left(x,t,u,\\frac{\\partial u}{\\partial x}\\right)\\right) + s\\left(x,t,u,\\frac{\\partial u}{\\partial x}\\right)${"altText":"c(x,t,u,(partial u)\/(partial x))(partial u)\/(partial t) = x^{-m}(partial)\/(partial x)(x^mf(x,t,u,(partial u)\/(partial x))) + s(x,t,u,(partial u)\/(partial x))"},
%[text] using the command `pdepe`. Some 2-D or 3-D equations are sufficiently symmetric that they can also be written in this form. 
% m controls the symmetry of the problem
% m=0 is linear, m=1 is cylindrical, and m=2 is spherical
m = 0;
% Choose the resolution you need in space
xMesh = linspace(0,L,80);
% You can space time values closer or farther apart if you know
% something about the expected behavior of the system
smtSteps = linspace(0,0.03,121);
lrgtSteps = linspace(0.03,5,51);
tMesh = [smtSteps lrgtSteps(2:end)];
%[text] %[text:anchor:M_140844DE] Define the necessary [helper functions](internal:H_C529CC08). Prior to R2024a, functions are collected at the end of a live script. In R2024a or later you may write functions anywhere in a live script.
%[text] %[text:anchor:H_C529CC08] ### Helper Functions for use with `pdepe`
function [c,f,s] = heatpde(x,t,u,dudx)
% Set up a PDE for solving with the PDE toolbox
% c(x,t,u,u_x) is the coefficient of u_t
% f(x,t,u,u_x) is the flux term and must depend on u_x
% s(x,t,u,u_x) is the source term
gamma = 3;
c = 1;
f = gamma*dudx;
s = 0;
end

function u0 = heatIC(x)
% Set up the initial conditions u(t_0,x) = f(x)
u0 = nan(size(x));

for j = 1:length(x)
    xj = x(j);
    if xj <= 1
        u0(j) = 2*xj;
    elseif (xj>1) && (xj<=2)
        u0(j) = 5-3*xj;
    elseif (xj>2) && (xj<=3)
        u0(j) = -1;
    else
        u0(j) = 2*xj-7;
    end
end
end

function [pL,qL,pR,qR] = heatBC(xL,uL,xR,uR,t)
% Set up the boundary functions in the form
% p(x,t,u) + q(x,t)f(x,t,u,u_x) = 0
% L refers to the left-hand boundary and
% R refers to the right-hand boundary
pL = uL;
qL = 0;
pR = uR - 1;
qR = 0;
end
%[text] Then use these helper functions in `pdepe`.
sol = pdepe(m,@heatpde,@heatIC,@heatBC,xMesh,tMesh);
colormap hot
% imagesc(xMesh,tMesh,sol)
%colorbar
surf(xMesh,tMesh,sol)
xlabel('Distance x','interpreter','latex')
ylabel('Time t','interpreter','latex')
title('Heat Equation for $0 \le x \le 1$ and $0 \le t \le 5$','interpreter','latex')
view([-5.32 26.73])
%%
%[text] And plot your results.
p = plot(xMesh,heatIC(xMesh));
title("Solving the heat equation at $t = 0$", "Interpreter","latex")
subtitle("$\Delta t = $"+(tMesh(2)-tMesh(1)),"Interpreter","latex")
ax = p.Parent;
hold on
for j = 1:length(tMesh)
    delete(ax.Children(1:end-1))
    plot(xMesh,sol(j,:),SeriesIndex="none")
    pause(0.1)
    drawnow
    title("Solving the heat equation at $t = $"+round(tMesh(j),3))
    if j == length(smtSteps)+1
        subtitle("$\Delta t = $" + (lrgtSteps(2)-lrgtSteps(1)))
    end
end
hold off
%%
%[text] %[text:anchor:H_44256DEB] ### Further Explorations: solving systems of PDEs
%[text] Just as it is possible to extend first-order ODE solvers to handle solving systems of ODEs, it is possible to extend PDE solvers to handle systems of PDEs. 
